WITH flagged AS (SELECT *, CASE WHEN LAG(paid_at) OVER (PARTITION BY method ORDER BY paid_at, id) IS NULL OR paid_at > LAG(paid_at) OVER (PARTITION BY method ORDER BY paid_at, id) + INTERVAL '14' DAY THEN 1 ELSE 0 END AS is_new_burst FROM payments), sessions_payments AS (SELECT *, SUM(is_new_burst) OVER (PARTITION BY method ORDER BY paid_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM flagged) SELECT CASE WHEN session_no >= 7 THEN 'LARGE' ELSE 'SMALL' END AS session_no_tier, COUNT(*) FILTER (WHERE status = 'FAILED') AS failed_rows, PERCENTILE_APPROX(is_new_burst, 0.5) AS is_new_burst_p50, MIN(paid_at) AS first_seen, PERCENTILE_APPROX(is_new_burst, 0.95) AS is_new_burst_p95, ROUND(SUM(amount) / NULLIF(COUNT(CASE WHEN method = 'paypal' THEN 1 END), 0), 2) AS amount_per_paypal FROM sessions_payments GROUP BY CASE WHEN session_no >= 7 THEN 'LARGE' ELSE 'SMALL' END;
